/* Local task coordination UI. Clinical OS delivery is not connected. */
let taskView='tasks',taskDueFilter='all',taskPriorityFilter='all',taskQuery='',taskPatientFilter='all';
let pendingTaskEdit=null,pendingHandover=null;
const taskOwners=['Care team','Dr Morgan','Admin team'];
function taskToday(){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=k=>parts.find(p=>p.type===k).value;return `${get('year')}-${get('month')}-${get('day')}`;}
function validTaskDate(value){if(value==='')return true;if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const d=new Date(value+'T12:00:00Z');return !Number.isNaN(d.getTime())&&d.toISOString().slice(0,10)===value&&value>='2000-01-01'&&value<='2100-12-31';}
function taskDateLabel(value){if(!value||!validTaskDate(value))return 'No due date';return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Europe/London'}).format(new Date(value+'T12:00:00Z'));}
function taskIsOverdue(t){return !t.done&&!!t.dueDate&&validTaskDate(t.dueDate)&&t.dueDate<taskToday();}
function taskPriority(t){return t.priority==='time-sensitive'?'time-sensitive':'routine';}
function resetTaskFilters(){taskPatientFilter='all';taskFilter='all';taskOwner='all';taskDueFilter='all';taskPriorityFilter='all';taskQuery='';render();}
filteredTasks=function(){const q=taskQuery.trim().toLowerCase();return state.tasks.map((t,index)=>({...t,index})).filter(t=>(taskFilter==='all'||(taskFilter==='done'?t.done:!t.done))&&(taskOwner==='all'||t.owner===taskOwner)&&(taskPatientFilter==='all'||(taskPatientFilter==='team'?!t.patientId:t.patientId===taskPatientFilter))&&(taskPriorityFilter==='all'||taskPriority(t)===taskPriorityFilter)&&(taskDueFilter==='all'||(taskDueFilter==='overdue'?taskIsOverdue(t):taskDueFilter==='today'?t.dueDate===taskToday():!t.dueDate))&&(!q||[t.text,t.owner,t.patientId||'',demoPatients.find(p=>p.id===t.patientId)?.name||''].join(' ').toLowerCase().includes(q)));};
function taskOptions(options,value){return options.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('');}
function taskRowsMarkup(){const rows=filteredTasks();return `<div class="panel-head"><h2>${rows.length} ${rows.length===1?'task':'tasks'}</h2><span class="fine">Stored in this browser</span></div>${rows.length?rows.map(t=>`<article class="coordination-task ${t.done?'completed':''}"><input type="checkbox" aria-label="Mark ${esc(t.text)} ${t.done?'open':'complete'}" ${t.done?'checked':''} onchange="setTaskDone(${t.index},this.checked)"><div class="coordination-task-body"><button class="task-title" onclick="openTaskDetails(${t.index})">${esc(t.text)}</button><p>${t.patientId?esc(demoPatients.find(p=>p.id===t.patientId)?.name||t.patientId):'Team administration'} <span aria-hidden="true">·</span> ${esc(t.owner)}</p><div class="task-meta"><span class="${taskIsOverdue(t)?'task-overdue':''}">${taskIsOverdue(t)?'Overdue · ':''}${esc(taskDateLabel(t.dueDate))}</span>${taskPriority(t)==='time-sensitive'?'<span class="task-priority">Time-sensitive</span>':''}${t.sourceNote?'<span>Reviewed source attached</span>':''}${t.done?'<span>Completed</span>':''}</div></div><div class="task-row-actions">${demoPatients.some(p=>p.id===t.patientId)?`<button onclick="openTaskPatient(${t.index})" aria-label="Open patient record: ${esc(t.patientId)}">Patient record</button>`:''}${t.sourceNote?`<button onclick="showTaskSource(${t.index})">View source</button>`:''}<button onclick="openTaskDetails(${t.index})" aria-label="Edit task: ${esc(t.text)}">Details ${icon('arrow')}</button></div></article>`).join(''):'<div class="workspace-empty"><h3>No tasks match these filters</h3><p>Try another assignee, due date or search term.</p><button onclick="resetTaskFilters()">Clear filters</button></div>'}`;}
function updateTaskSearch(value){taskQuery=value;document.getElementById('task-results').innerHTML=taskRowsMarkup();}
function taskBoard(){return `<div class="task-toolbar"><div class="segmented" aria-label="Filter task status">${[['open','Open'],['done','Completed'],['all','All tasks']].map(([id,label])=>`<button aria-pressed="${taskFilter===id}" onclick="taskFilter='${id}';render()">${label}</button>`).join('')}</div><label class="search-field">${icon('search')}<input aria-label="Search tasks" placeholder="Search tasks or patients" value="${esc(taskQuery)}" oninput="updateTaskSearch(this.value)"></label></div><div class="task-filter-grid"><label for="task-patient-filter">Patient or team<select class="field" id="task-patient-filter" onchange="taskPatientFilter=this.value;render()">${taskOptions([['all','All patients and team tasks'],['team','Team administration only'],...demoPatients.map(p=>[p.id,p.name+' · '+p.id])],taskPatientFilter)}</select></label><label>Assigned to<select class="field" onchange="taskOwner=this.value;render()">${taskOptions([['all','Everyone'],...taskOwners.map(o=>[o,o])],taskOwner)}</select></label><label>Due date<select class="field" onchange="taskDueFilter=this.value;render()">${taskOptions([['all','Any date'],['overdue','Overdue'],['today','Due today'],['none','No due date']],taskDueFilter)}</select></label><label>Administrative priority<select class="field" onchange="taskPriorityFilter=this.value;render()">${taskOptions([['all','Any priority'],['routine','Routine'],['time-sensitive','Time-sensitive']],taskPriorityFilter)}</select></label><button class="text-btn" onclick="resetTaskFilters()">Clear filters</button></div><section class="panel" id="task-results" aria-label="Task results" aria-live="polite">${taskRowsMarkup()}</section><p class="coordination-footnote">Dates use UK time. Priority is set by the task author. It does not represent a clinical risk assessment.</p>`;}
function handoverDrafts(){if(!Array.isArray(state.handoverDrafts))state.handoverDrafts=[];return state.handoverDrafts;}
function handoverSourceChanged(d){const r=state.patientRecords[d.patientId];return !r||!r.signed||r.version!==d.sourceVersion||r.revision!==d.sourceRevision||r.note!==d.sourceNote;}
function handoverBoard(){const drafts=handoverDrafts();return `<div class="handover-explainer"><div><span class="eyebrow">Clear ownership, preserved context</span><h2>Prepare the next step</h2><p>Choose a reviewed document, add a handover message and retain its exact source. Drafts stay in this browser.</p></div><span class="pill">Delivery not connected</span></div><section class="panel"><div class="panel-head"><h2>${drafts.length} handover ${drafts.length===1?'draft':'drafts'}</h2><span class="fine">None sent</span></div>${drafts.length?drafts.map((d,i)=>`<article class="handover-card"><div><h3>${esc(d.patientName)}</h3><p>For ${esc(d.recipient)} · Note v${esc(d.sourceVersion)}</p><p class="handover-message">${esc(d.message)}</p><div class="task-meta"><span>Draft · Not sent</span>${handoverSourceChanged(d)?'<span class="task-overdue">Source has changed — review needed</span>':'<span>Matches current signed note</span>'}</div></div><button onclick="showHandoverDraft(${i})">Review draft</button></article>`).join(''):'<div class="workspace-empty"><span class="empty-symbol">'+icon('document')+'</span><h3>No handover drafts yet</h3><p>Start with a signed document so the receiving team can see the reviewed source.</p><button onclick="openHandoverComposer()">Prepare a handover</button></div>'}</section>`;}
tasks=function(){const open=state.tasks.filter(t=>!t.done).length,overdue=state.tasks.filter(taskIsOverdue).length;return pageHeading('Tasks & handovers','Own the next step. Keep the reviewed source close.',`<button onclick="openHandoverComposer()">Prepare handover</button><button class="primary" onclick="openTaskComposer()">${icon('plus')} Add task</button>`)+`<div class="coordination-summary"><span><strong>${open}</strong> open tasks</span><span><strong>${overdue}</strong> overdue</span><span><strong>${handoverDrafts().length}</strong> handover drafts</span><small>Local workspace · No external delivery</small></div><div class="coordination-tabs segmented" aria-label="Tasks and handovers"><button aria-pressed="${taskView==='tasks'}" onclick="taskView='tasks';render()">Tasks</button><button aria-pressed="${taskView==='handovers'}" onclick="taskView='handovers';render()">Handover drafts</button></div>${taskView==='handovers'?handoverBoard():taskBoard()}`;};
function taskEditorFields(t={}){return `<div class="form-group"><label for="task-description">Task description</label><input class="field" id="task-description" name="description" maxlength="150" value="${esc(t.text||'')}" required placeholder="Use fictional information only"></div><div class="task-edit-grid"><label for="task-assignee">Assign to<select class="field" id="task-assignee" name="owner">${taskOptions(taskOwners.map(o=>[o,o]),t.owner||'Care team')}</select></label><label for="task-due">Due date (optional)<input class="field" id="task-due" name="dueDate" type="date" min="2000-01-01" max="2100-12-31" value="${esc(t.dueDate||'')}"></label></div><div class="form-group"><label for="task-priority">Administrative priority</label><select class="field" id="task-priority" name="priority">${taskOptions([['routine','Routine'],['time-sensitive','Time-sensitive']],taskPriority(t))}</select></div><div class="form-group"><label for="task-context">Task notes (optional)</label><textarea class="field" id="task-context" name="context" maxlength="2000" rows="3">${esc(t.context||'')}</textarea></div><p id="task-edit-error" class="task-error" role="alert"></p><p class="fine">Saved in this browser. No external task, notification or clinical risk assessment is created.</p>`;}
openTaskComposer=function(){pendingTaskEdit=null;modal('Add a team task',`<form id="task-composer" onsubmit="event.preventDefault();saveComposedTask(this)">${taskEditorFields()}</form>`,`<button onclick="closeModal()">Cancel</button><button class="primary" type="submit" form="task-composer">Save task</button>`);document.getElementById('task-description')?.focus?.();};
function readTaskEditor(form){const v={text:form.description.value.trim(),owner:form.owner.value,dueDate:form.dueDate?.value||'',priority:form.priority?.value||'routine',context:form.context?.value.trim()||''};if(!v.text||v.text.length>150||!taskOwners.includes(v.owner)||!validTaskDate(v.dueDate)||!['routine','time-sensitive'].includes(v.priority)||v.context.length>2000){document.getElementById('task-edit-error').textContent='Check the description, assignee, date and priority before saving.';return null;}return v;}
saveComposedTask=function(form){const v=readTaskEditor(form);if(!v)return;state.tasks.push({...v,done:false});const saved=audit('Local team task added.');closeModal();taskView='tasks';taskPatientFilter='all';taskFilter='open';taskOwner='all';taskDueFilter='all';taskPriorityFilter='all';taskQuery='';nav('T');toast(saved?'Task saved in this workspace.':'Task remains in this tab only. Saving failed.');};
function openTaskDetails(index){const t=state.tasks[index];if(!t)return;pendingTaskEdit={index,snapshot:JSON.stringify(t)};modal('Task details',`<form id="task-details" onsubmit="event.preventDefault();saveTaskDetails(this)"><p class="fine">${t.patientId?esc(demoPatients.find(p=>p.id===t.patientId)?.name||t.patientId)+' · ':''}${t.done?'Completed':'Open'}${t.sourceNote?' · Reviewed source retained':''}</p>${t.patientId?`<div class="handover-identity"><strong>${esc(demoPatients.find(p=>p.id===t.patientId)?.name||'Patient unavailable')}</strong><span>${esc(t.patientId)} · Linked patient cannot be changed here</span></div>`:''}${taskEditorFields(t)}${t.sourceNote?`<details class="task-source"><summary>Reviewed source attached to this task</summary><pre class="review-copy">${esc(t.sourceNote)}</pre></details>`:''}</form>`,`<button onclick="closeModal()">Cancel</button><button class="primary" type="submit" form="task-details">Save changes</button>`);document.getElementById('task-description')?.focus?.();}
function openTaskPatient(index){const t=state.tasks[index];if(!t||!demoPatients.some(p=>p.id===t.patientId))return;openPatient(t.patientId,'record');}
function showPatientTasks(id){if(!demoPatients.some(p=>p.id===id))return;taskView='tasks';taskPatientFilter=id;taskFilter='all';taskOwner='all';taskDueFilter='all';taskPriorityFilter='all';taskQuery='';nav('T');}
function saveTaskDetails(form){const p=pendingTaskEdit;if(!p)return;const t=state.tasks[p.index];if(!t||JSON.stringify(t)!==p.snapshot){document.getElementById('task-edit-error').textContent='This task changed while you were editing. Close and reopen its details.';return;}const v=readTaskEditor(form);if(!v)return;Object.assign(t,v);pendingTaskEdit=null;const saved=audit('Local task details updated.');closeModal();render();toast(saved?'Task details saved.':'Task changes remain in this tab only. Saving failed.');}
function openHandoverComposer(values={}){pendingHandover=null;const rows=allDocumentRows().filter(x=>x.record.signed);if(!rows.length){modal('A signed document is needed','<p>Review and sign an example document before preparing a source-linked handover.</p><p class="fine">No handover has been created.</p>','<button onclick="closeModal()">Close</button><button class="primary" onclick="closeModal();nav(\'review\')">Open review queue</button>');return;}modal('Prepare a handover',`<form id="handover-composer" onsubmit="event.preventDefault();reviewHandoverDraft(this)"><div class="form-group"><label for="handover-patient">Signed source document</label><select class="field" id="handover-patient" name="patientId">${taskOptions(rows.map(x=>[x.patient.id,`${x.patient.name} · Note v${x.record.version}`]),values.patientId||state.selectedPatientId)}</select></div><div class="form-group"><label for="handover-recipient">Intended recipient</label><select class="field" id="handover-recipient" name="recipient">${taskOptions(taskOwners.map(o=>[o,o]),values.recipient||'Care team')}</select></div><div class="form-group"><label for="handover-message">Handover message</label><textarea class="field" id="handover-message" name="message" required maxlength="2000" rows="4" placeholder="Describe the administrative next step. Use fictional information only.">${esc(values.message||'')}</textarea></div><p id="handover-error" class="task-error" role="alert"></p><p class="fine">Recipients are example roles. Preparing a draft does not send a message or assign a task.</p></form>`,`<button onclick="closeModal()">Cancel</button><button class="primary" type="submit" form="handover-composer">Review draft</button>`);}
function reviewHandoverDraft(form){const p=demoPatients.find(x=>x.id===form.patientId.value),r=p&&state.patientRecords[p.id],message=form.message.value.trim(),recipient=form.recipient.value;if(!p||!r?.signed||!r.note||!message||message.length>2000||!taskOwners.includes(recipient)){document.getElementById('handover-error').textContent='Choose a signed document, recipient and handover message.';return;}pendingHandover={patientId:p.id,patientName:p.name,sourceVersion:r.version,sourceRevision:r.revision,sourceNote:r.note,recipient,message};modal('Review handover draft',handoverDetailMarkup(pendingHandover)+`<label class="consent"><input type="checkbox" id="handover-confirm">I have checked the patient, intended recipient, message and source.</label><p id="handover-review-error" class="task-error" role="alert"></p>`,`<button onclick="closeModal();pendingHandover=null">Cancel</button><button onclick="editPendingHandover()">Back to edit</button><button class="primary" onclick="saveHandoverDraft()">Save draft</button>`);}
function editPendingHandover(){const d=pendingHandover;if(!d)return;const r=state.patientRecords[d.patientId];if(!r?.signed){document.getElementById('handover-review-error').textContent='This source is no longer reviewed. Your message remains here; review the document before preparing a new draft.';return;}openHandoverComposer({patientId:d.patientId,recipient:d.recipient,message:d.message});document.getElementById('handover-message')?.focus?.();}
function handoverSnapshotKey(d){return JSON.stringify([d.patientId,d.sourceVersion,d.sourceRevision,d.sourceNote,d.recipient,d.message]);}
function handoverDetailMarkup(d){return `<div class="handover-identity"><strong>${esc(d.patientName)}</strong><span>${esc(d.patientId)} · Note v${esc(d.sourceVersion)}</span></div><p><strong>Intended recipient:</strong> ${esc(d.recipient)}</p><p class="handover-message">${esc(d.message)}</p><details class="task-source" open><summary>Exact signed source document</summary><pre class="review-copy">${esc(d.sourceNote)}</pre></details><p class="notice">Draft only · Not sent. Clinical OS delivery is not connected.</p>`;}
function saveHandoverDraft(){const d=pendingHandover;if(!d)return;const r=state.patientRecords[d.patientId];if(handoverSourceChanged(d)||r.revision!==d.sourceRevision){document.getElementById('handover-review-error').textContent='The source document changed. Close this review and prepare a new draft.';return;}if(!document.getElementById('handover-confirm')?.checked){document.getElementById('handover-review-error').textContent='Check the draft and confirm before saving.';return;}const existing=handoverDrafts().some(x=>handoverSnapshotKey(x)===handoverSnapshotKey(d));let saved;if(existing){saved=save();}else{handoverDrafts().unshift({...d,createdAt:new Date().toISOString(),deliveryStatus:'not-sent'});saved=audit('Local handover draft prepared. No message sent.');}pendingHandover=null;closeModal();taskView='handovers';nav('T');toast(saved?(existing?'An identical handover draft is already prepared. Not sent.':'Handover draft saved. Not sent.'):'Handover remains in this tab only. Saving failed. Not sent.');}
function showHandoverDraft(index){const d=handoverDrafts()[index];if(!d)return;modal('Handover draft',`${handoverSourceChanged(d)?'<p class="notice">The source has changed since this draft was prepared. This draft retains the earlier source and needs review.</p>':''}${handoverDetailMarkup(d)}`,`<button onclick="closeModal()">Close</button><button onclick="exportHandoverDraft(${index})">Export draft</button>`);}
function exportHandoverDraft(index){const d=handoverDrafts()[index];if(!d)return;download(`${d.patientId}-handover-draft.txt`,`HANDOVER DRAFT — NOT SENT\nSynthetic local workspace\nPatient: ${d.patientName} (${d.patientId})\nIntended recipient: ${d.recipient}\nPrepared: ${d.createdAt}\nSource: note v${d.sourceVersion}\n${handoverSourceChanged(d)?'SOURCE CHANGED — REVIEW NEEDED\n':''}\n${d.message}\n\nEXACT SIGNED SOURCE\n${d.sourceNote}\n\nClinical OS delivery is not connected.`, 'text/plain');}
const taskUiSelectPatient=selectPatient;
selectPatient=function(id){pendingTaskEdit=null;pendingHandover=null;return taskUiSelectPatient(id);};
document.getElementById('dialog').addEventListener('close',()=>{pendingTaskEdit=null;pendingHandover=null;});
document.getElementById('dialog').addEventListener('cancel',()=>{pendingTaskEdit=null;pendingHandover=null;});
render();
